#!/usr/bin/env python3
"""Focused validation harness for the gfileattribute integer-overflow fix.

Runs inside the clean replay checkout created by validate_candidate.py (its cwd).
It extracts the real valid_char()/escape_byte_string() functions from:
  * candidate: the working-tree gio/gfileattribute.c (patch applied)
  * baseline:  git show HEAD:gio/gfileattribute.c (unpatched target)
compiles both with minimal g_malloc/g_strdup stubs, and runs:
  * small positive escaping cases on the candidate
  * a 2^30-char all-invalid string on the candidate (must allocate 4*N+1 and escape correctly)
  * the same input on the baseline (must under-allocate; bounded run exits 42 at g_malloc,
    unbounded run is expected to crash)
"""
import os
import shutil
import subprocess
import sys

REPO = os.getcwd()
OUTDIR = "/workspace/repo/.patch-port/results/focus-build"
BUILD = os.path.join(OUTDIR, "build")

TEMPLATE = r"""
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <stdio.h>

typedef int gboolean;

static size_t g_expected_min = 0;
static void *g_malloc (size_t n) {
  fprintf (stderr, "GMALLOC %zu\n", n);
  if (g_expected_min != 0 && n < g_expected_min) {
    fprintf (stderr, "INSUFFICIENT_ALLOC n=%zu expected_min=%zu\n", n, g_expected_min);
    _exit (42);
  }
  void *p = malloc (n);
  if (!p) { fprintf (stderr, "MALLOC_FAILED %zu\n", n); _exit (3); }
  return p;
}
static char *g_strdup (const char *s) {
  size_t n = strlen (s) + 1;
  char *p = malloc (n);
  if (!p) _exit (3);
  memcpy (p, s, n);
  return p;
}

__FUNCS__

static int check (const char *in, const char *expected, const char *label) {
  char *out = escape_byte_string (in);
  int ok = out != NULL && strcmp (out, expected) == 0;
  printf ("SMALL %s %s in=[%s] out=[%s] expected=[%s]\n",
          label, ok ? "OK" : "BAD", in, out ? out : "(null)", expected);
  free (out);
  return ok ? 0 : 1;
}

int main (int argc, char **argv) {
  if (argc < 2) { fprintf (stderr, "usage: %s small|large|large_unbounded\n", argv[0]); return 2; }
  if (strcmp (argv[1], "small") == 0) {
    int bad = 0;
    bad |= check ("hello", "hello", "all-valid");
    bad |= check ("", "", "empty");
    bad |= check ("a\tb", "a\\x09b", "tab");
    bad |= check ("\\", "\\x5c", "backslash");
    bad |= check ("a\x01\x7f\xffz", "a\\x01\\x7f\\xffz", "controls");
    if (bad) { printf ("SMALL RESULT BAD\n"); return 1; }
    printf ("SMALL RESULT OK\n");
    return 0;
  }
  if (strcmp (argv[1], "large") == 0 || strcmp (argv[1], "large_unbounded") == 0) {
    size_t N = (size_t) 1 << 30;              /* 2^30 invalid chars */
    size_t expected_len = 4 * N + 1;          /* len + num_invalid*3 + 1 */
    char *s = malloc (N + 1);
    if (!s) { fprintf (stderr, "input malloc failed\n"); return 3; }
    memset (s, '\\', N);
    s[N] = 0;
    if (strcmp (argv[1], "large") == 0)
      g_expected_min = expected_len;          /* require the correct allocation size */
    char *out = escape_byte_string (s);
    if (!out) { printf ("LARGE NULL N=%zu expected_len=%zu\n", N, expected_len); return 5; }
    int ok = out[0]=='\\' && out[1]=='x' && out[2]=='5' && out[3]=='c' &&
             out[4*N-4]=='\\' && out[4*N-3]=='x' && out[4*N-2]=='5' && out[4*N-1]=='c' &&
             out[4*N] == '\0';
    printf ("LARGE %s N=%zu expected_len=%zu\n", ok ? "OK" : "BAD", N, expected_len);
    free (out); free (s);
    return ok ? 0 : 4;
  }
  fprintf (stderr, "unknown mode\n");
  return 2;
}
"""


def extract_functions(src: str) -> str:
    key = "static gboolean\nvalid_char (char c)"
    i = src.index(key)
    j = src.index("escape_byte_string (const char *str)", i)
    brace = src.index("{", j)
    depth = 0
    k = brace
    while k < len(src):
        ch = src[k]
        if ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                return src[i:k + 1]
        k += 1
    raise RuntimeError("could not extract escape_byte_string")


def build(name: str, functions: str) -> str:
    src = TEMPLATE.replace("__FUNCS__", functions)
    path = os.path.join(BUILD, name + ".c")
    exe = os.path.join(BUILD, name)
    with open(path, "w") as handle:
        handle.write(src)
    cmd = ["gcc", "-std=gnu11", "-O0", "-g", "-w", "-o", exe, path]
    result = subprocess.run(cmd, capture_output=True, text=True)
    if result.returncode != 0:
        print("COMPILE FAILED", name)
        print(result.stderr)
        sys.exit(9)
    return exe


def run(exe: str, mode: str, timeout: int = 120):
    try:
        result = subprocess.run([exe, mode], capture_output=True, text=True,
                                errors="replace", timeout=timeout)
        return result.returncode, result.stdout, result.stderr
    except subprocess.TimeoutExpired as exc:
        stdout = exc.stdout.decode() if isinstance(exc.stdout, bytes) else (exc.stdout or "")
        return 124, stdout, "TIMEOUT"


def main() -> int:
    candidate_src = open(os.path.join(REPO, "gio", "gfileattribute.c")).read()
    baseline_src = subprocess.run(
        ["git", "-C", REPO, "show", "HEAD:gio/gfileattribute.c"],
        capture_output=True, text=True, check=True).stdout

    if "SIZE_MAX" not in candidate_src or "size_t num_invalid" not in candidate_src:
        print("CANDIDATE FUNCTION NOT PATCHED AS EXPECTED")
        return 8

    shutil.rmtree(OUTDIR, ignore_errors=True)
    os.makedirs(BUILD)
    cand = build("candidate", extract_functions(candidate_src))
    base = build("baseline", extract_functions(baseline_src))

    failures = []

    rc, out, err = run(cand, "small")
    print("=== candidate small rc=%d ===" % rc)
    print(out.strip())
    if rc != 0 or "SMALL RESULT OK" not in out:
        failures.append("candidate small positive test")

    rc, out, err = run(cand, "large")
    print("=== candidate large (2^30 invalid chars) rc=%d ===" % rc)
    print(out.strip())
    print(err.strip())
    if rc != 0 or "LARGE OK" not in out or "GMALLOC %d" % (4 * (1 << 30) + 1) not in err:
        failures.append("candidate large overflow regression")

    rc, out, err = run(base, "large")
    print("=== baseline large bounded rc=%d ===" % rc)
    print(out.strip())
    print(err.strip())
    if rc != 42 or "INSUFFICIENT_ALLOC" not in err or "GMALLOC 1" not in err:
        failures.append("baseline under-allocation proof")

    rc, out, err = run(base, "large_unbounded", timeout=90)
    print("=== baseline large unbounded rc=%d ===" % rc)
    print(out.strip())
    print((err.strip())[:2000])
    if rc == 0:
        failures.append("baseline unbounded did not fail")

    if failures:
        print("FOCUSED TEST FAILURES: " + "; ".join(failures))
        return 1
    print("FOCUSED TESTS PASSED")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

